<script setup lang="ts">import {ref} from 'vue';import {Plus,UserRound,X,ShieldCheck} from 'lucide-vue-next';import WorkshopHeader from '../../components/WorkshopHeader.vue';import {useWorkshop} from '../../composables/useWorkshop';import type {EmployeeRole} from '../../data/company';const {state,addEmployee,toggleEmployee}=useWorkshop();const adding=ref(false);const roles:EmployeeRole[]=['Owner','Manager','Service advisor','Technician','Reception','Administrator'];const form=ref({name:'',email:'',role:'Technician' as EmployeeRole,location:'Ljubljana Center'});const invite=()=>{addEmployee({id:crypto.randomUUID(),...form.value,active:true});adding.value=false;form.value.name='';form.value.email=''}
</script>
<template><WorkshopHeader title="Employees & roles" subtitle="Manage team access" back="/workshop/more"><button @click="adding=true" class="btn-primary !min-h-10"><Plus :size="16"/>Invite</button></WorkshopHeader><div class="mx-auto max-w-5xl p-5 md:p-8"><div class="overflow-hidden rounded-2xl border bg-white"><div v-for="e in state.employees" class="grid gap-3 border-b p-5 last:border-0 md:grid-cols-[1fr_180px_180px_100px] md:items-center"><div class="flex items-center gap-3"><span class="grid h-10 w-10 place-items-center rounded-full bg-stone-100"><UserRound :size="18"/></span><span><strong class="block text-sm">{{e.name}}</strong><small class="text-muted">{{e.email}}</small></span></div><span class="flex items-center gap-1 text-sm"><ShieldCheck :size="15" class="text-accent"/>{{e.role}}</span><span class="text-sm text-muted">{{e.location}}</span><button @click="toggleEmployee(e.id)" class="rounded-full px-3 py-1.5 text-xs font-semibold" :class="e.active?'bg-emerald-50 text-success':'bg-stone-100 text-muted'">{{e.active?'Active':'Inactive'}}</button></div></div><section class="mt-6 rounded-2xl border border-dashed p-5"><h2 class="font-semibold">Permission management</h2><p class="mt-2 text-sm leading-6 text-muted">Owners and managers can configure access to customers, pricing, campaigns, quotes, work orders and company settings for each role.</p><button class="btn-secondary mt-4">Configure role permissions</button></section></div><Teleport to="body"><div v-if="adding" class="fixed inset-0 z-[90] flex items-end bg-black/30" @click.self="adding=false"><form @submit.prevent="invite" class="mx-auto w-full max-w-xl rounded-t-3xl bg-white p-6 pb-10"><div class="flex justify-between"><h2 class="text-2xl font-semibold">Invite employee</h2><button type="button" @click="adding=false" class="grid h-10 w-10 place-items-center rounded-full bg-stone-100"><X :size="18"/></button></div><label class="mt-6 block"><span class="label">Name</span><input v-model="form.name" class="field" required/></label><label class="mt-4 block"><span class="label">Email</span><input v-model="form.email" type="email" class="field" required/></label><div class="mt-4 grid grid-cols-2 gap-3"><label><span class="label">Role</span><select v-model="form.role" class="field"><option v-for="r in roles">{{r}}</option></select></label><label><span class="label">Location</span><select v-model="form.location" class="field"><option>Ljubljana Center</option><option>Domžale</option></select></label></div><button class="btn-primary mt-6 w-full">Send invitation</button></form></div></Teleport></template>
